files.content:
html,
body,
#app {
  min-height: 100%;
  background:
    radial-gradient(circle at top left, hsl(var(--primary) / 0.035), transparent 28%),
    linear-gradient(
      180deg,
      hsl(var(--app-shell)) 0%,
      hsl(var(--background)) 55%,
      hsl(var(--content-muted)) 100%
    );
  color: hsl(var(--foreground));
}

body {
  margin: 0;
  background-attachment: fixed;
}

* {
  box-sizing: border-box;
}
